// Synthetic transport only. No final scientific object construction in run().
import assert from 'node:assert/strict';
import {evaluateUnifiedOpportunityOceanConditionsV1} from '../../server.js';
export const thermalModes={uniform:{north:25,east:25,south:25,west:25},weak:{north:25.3,east:25,south:25,west:25},moderate:{north:26,east:25,south:25,west:25},strong:{north:28,east:27,south:24,west:25},partial:{north:28,east:null,south:null,west:25},missing:{north:null,east:null,south:null,west:null}};
export const currentModes={convergenceOnly:{north:[0,-.06],east:[-.06,0],south:[0,.06],west:[.06,0]},uniform:{all:[.5,.2]},edge:{north:[.5,.2],east:[2,0],south:[.5,.2],west:[.1,0]},shear:{north:[1,0],east:[.1,0],south:[-1,0],west:[.1,0]},convergence:{north:[0,-1],east:[-1,0],south:[0,1],west:[1,0]},divergence:{north:[0,1],east:[1,0],south:[0,-1],west:[-1,0]},rotation:{north:[1,0],east:[0,-1],south:[-1,0],west:[0,1]},zero:{all:[0,-0]},missing:{all:null}};

export async function run(t,config={},clock=Date.parse('2300-01-01')){const {thermal='uniform',current='uniform',coordinates=[25,-90],center=25,chlorophyll=.1,sourceTime='2026-09-24T00:00:00Z',extras={}}=config;const [latitude,longitude]=coordinates,requests=[];const now=t.mock.method(Date,'now',()=>clock),warn=t.mock.method(console,'warn',()=>{});const transport=t.mock.method(globalThis,'fetch',async input=>{const u=new URL(input),weather=u.hostname==='api.open-meteo.com',marine=u.hostname==='marine-api.open-meteo.com',noaa=u.hostname.endsWith('.noaa.gov');assert(weather||marine||noaa,'Forbidden service');requests.push(String(u));if(weather&&config.weatherRejected)throw Error('Synthetic weather rejection');const decoded=decodeURIComponent(u.search),chl=decoded.includes('chlor_a');let lat=Number(u.searchParams.get('latitude')),lon=Number(u.searchParams.get('longitude'));if(noaa){const nums=[...decoded.matchAll(/\[\((-?\d+(?:\.\d+)?)\)\]/g)].map(x=>Number(x[1]));[lat,lon]=nums;}const role=lat>latitude?'north':lat<latitude?'south':lon>longitude?'east':lon<longitude?'west':'center';const uv=role==='center'?[.5,.2]:(config.vectors?.[role] ?? currentModes[current].all??currentModes[current][role]);if(noaa&&!chl&&config.currentRejected)throw Error('Synthetic current rejection'); const currentMissing=current==='missing'||uv===null||config.missingRoles?.includes(role);const directional=marine&&u.searchParams.get('current')==='sea_surface_temperature';return {ok:true,json:async()=>noaa?{table:{columnNames:['time','latitude','longitude','chlor_a','u_current','v_current'],rows:(chl?chlorophyll===null:currentMissing)?[]:[[(chl?sourceTime:(Object.hasOwn(config.currentTimes??{},role)?config.currentTimes[role]:('currentTime' in config?config.currentTime:sourceTime))),lat,lon,chlorophyll,...(uv??[null,null])]]}}:{latitude:lat,longitude:lon,current:{time:sourceTime,wind_speed_10m:4,wind_gusts_10m:6,wind_direction_10m:90,sea_surface_temperature:directional?thermalModes[thermal][role]:center,wave_height:1,wave_direction:90,wave_period:7,swell_wave_height:.5,swell_wave_direction:90,swell_wave_period:8}}};});try{const r=await evaluateUnifiedOpportunityOceanConditionsV1({...extras,assessment:{contractVersion:'pelora-scientific-assessment-v1',assessmentAt:'2026-09-26T01:00:00Z'},candidates:[{id:'physics-boundary',candidateClass:'open-water',coordinates,eligibility:{eligible:true}}],bearerToken:null,concurrency:1});const record=r.controlledEvaluation.evaluation.results[0];assert.equal(record.status,'fulfilled');return {ocean:record.value.oceanConditions,requests};}finally{transport.mock.restore();now.mock.restore();warn.mock.restore();}}

export const inward = speed => ({north:[0,-speed],east:[-speed,0],south:[0,speed],west:[speed,0]});
